interface Emitter<TEvents extends Record<string, unknown>> {
    on<K extends keyof TEvents>(event: K, handler: (payload: TEvents[K]) => void): void
    emit<K extends keyof TEvents>(event: K, payload: TEvents[K]): void
}

type AppEvents = {
    login: { userId: number }
    logout: { userId: number; reason: string }
    error: Error
}

class SimpleEmitter<TEvents extends Record<string, unknown>> implements Emitter<TEvents> {
    private handlers = new Map<keyof TEvents, ((payload: any) => void)[]>()

    on<K extends keyof TEvents>(event: K, handler: (payload: TEvents[K]) => void): void {
        const list = this.handlers.get(event) ?? []
        list.push(handler)
        this.handlers.set(event, list)
    }

    emit<K extends keyof TEvents>(event: K, payload: TEvents[K]): void {
        this.handlers.get(event)?.forEach(h => h(payload))
    }
}

