class EventBus<Events extends Record<string, unknown>> {
    private handlers: { [K in keyof Events]?: ((p: Events[K]) => void)[] } = {}
    on<K extends keyof Events>(e: K, fn: (p: Events[K]) => void) { (this.handlers[e] ??= []).push(fn) }
    emit<K extends keyof Events>(e: K, payload: Events[K]) { this.handlers[e]?.forEach(fn => fn(payload)) }
}

