class Result<T> {
    private constructor(private readonly value?: T, private readonly error?: string) {}
    static ok<T>(v: T) { return new Result<T>(v) }
    static fail<T>(e: string) { return new Result<T>(undefined, e) }
    map<U>(fn: (v: T) => U): Result<U> { return this.error ? Result.fail<U>(this.error) : Result.ok(fn(this.value as T)) }
    unwrapOr(fallback: T): T { return this.error ? fallback : (this.value as T) }
}

