class Stack<T> { private a: T[] = []; push(x: T) { this.a.push(x) } pop() { return this.a.pop() } get empty() { return this.a.length === 0 } }
function balanced(s: string) {
    const st = new Stack<string>(), pairs: Record<string, string> = { ")": "(", "]": "[" }
    for (const ch of s) { if (ch === "(" || ch === "[") st.push(ch); else if (ch in pairs && st.pop() !== pairs[ch]) return false }
    return st.empty
}
