class TwoStackQueue<T> {
    private inbox: T[] = []
    private outbox: T[] = []
    enqueue(x: T) { this.inbox.push(x) }
    dequeue(): T | undefined {
        if (!this.outbox.length) while (this.inbox.length) this.outbox.push(this.inbox.pop()!)
        return this.outbox.pop()
    }
}
