class Dog { name: string; constructor(n: string) { this.name = n } }
console.log(make(Dog, "Rex"))

function getters<T extends object>(obj: T) {
    return (Object.keys(obj) as (keyof T & string)[]).map(k => `get${k[0].toUpperCase()}${k.slice(1)}`)
}
console.log(getters({ name: "a", age: 1 }))

const merge = <A extends object, B extends object>(a: A, b: B): A & B => ({ ...a, ...b })
console.log(merge({ x: 1 }, { y: "ikki" }))
// merge(1, 2) — xato: number obyekt emas

function where<T, K extends keyof T>(arr: T[], key: K, value: T[K]) { return arr.filter(x => x[key] === value) }
const rows = [{ city: "Buxoro", pop: 280 }, { city: "Xiva", pop: 95 }, { city: "Buxoro", pop: 1 }]
console.log(where(rows, "city", "Buxoro").length)

function counter<K extends PropertyKey>(keys: K[]): Record<K, number> {
    return keys.reduce((acc, k) => ({ ...acc, [k]: 0 }), {} as Record<K, number>)
}
console.log(counter(["a", "b"]), counter([1, 2]))

function head<T extends readonly unknown[]>(arr: T): T[0] { return arr[0] }
const h = head(["x", 2] as const)
console.log(h)

function wrapError<E extends Error>(e: E, prefix: string): E { e.message = `${prefix}: ${e.message}`; return e }
const err = wrapError(new RangeError("chegaradan tashqari"), "Validatsiya")
console.log(err.name, err.message)

async function time<F extends () => Promise<unknown>>(f: F): Promise<Awaited<ReturnType<F>>> {
    return (await f()) as Awaited<ReturnType<F>>
}
console.log(await time(async () => ({ ok: true })))

interface Comparable<T> { compareTo(o: T): number }
function maxOf<T extends Comparable<T>>(xs: T[]): T { return xs.reduce((m, x) => (x.compareTo(m) > 0 ? x : m)) }
class Ver implements Comparable<Ver> { n: number; constructor(n: number) { this.n = n } compareTo(o: Ver) { return this.n - o.n } }
console.log(maxOf([new Ver(3), new Ver(9), new Ver(5)]).n)

function prefixKeys<T extends Record<string, unknown>, P extends string>(o: T, p: P) {
    return Object.fromEntries(Object.entries(o).map(([k, v]) => [`${p}${k}`, v])) as { [K in keyof T as `${P}${K & string}`]: T[K] }
}
const pk = prefixKeys({ id: 1, name: "a" }, "user_")
console.log(pk.user_id, pk.user_name)

function instances<C extends new () => object>(C: C, n: number): InstanceType<C>[] {
    return Array.from({ length: n }, () => new C() as InstanceType<C>)
}
class Token { static n = 0; id = ++Token.n }
console.log(instances(Token, 2))

type MethodKeys<T> = { [K in keyof T]: T[K] extends (...a: any[]) => any ? K : never }[keyof T]
function invoke<T, K extends MethodKeys<T>>(obj: T, k: K) { return (obj[k] as () => unknown)() }
const svc = { name: "svc", start() { return "boshlandi" }, stop() { return "to'xtadi" } }
console.log(invoke(svc, "start"), invoke(svc, "stop"))

type Json = string | number | boolean | null | Json[] | { [k: string]: Json }
